<script setup>
import {Smartphone,Copy,RefreshCw,Wifi,LoaderCircle} from 'lucide-vue-next';
import ConnectionQRCode from './ConnectionQRCode.vue';
defineProps({status:Object,busy:Boolean});const emit=defineEmits(['toggle','rotate','copy']);
function expires(value){return new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
</script>
<template><div class="settings-group phone-settings"><h2><Smartphone :size="21"/>iPhone 连接</h2><div class="phone-settings-heading"><div><strong>{{status?.enabled?'手机连接已开启':'让 iPhone 使用 Mac 下载'}}</strong><p>同一 Wi-Fi 内，用 iPhone 相机扫描二维码，在 Safari 输入配对码。文件由 Mac 下载，完成后可保存到手机。</p></div><button :class="{primary:!status?.enabled}" :disabled="busy" @click="emit('toggle',!status?.enabled)"><LoaderCircle v-if="busy" :size="17" class="spin"/><Wifi v-else :size="17"/>{{status?.enabled?'停止手机连接':'开启手机连接'}}</button></div><template v-if="status?.enabled"><div class="phone-pair-info"><div><label>8 位配对码</label><code class="phone-pair-code">{{status.code}}</code><p>有效至 {{expires(status.expiresAt)}} · 已连接 {{status.clients||0}} 台设备</p></div><button :disabled="busy" @click="emit('rotate')"><RefreshCw :size="17"/>换一个配对码</button></div><div class="phone-addresses"><div v-for="address in status.addresses" :key="address" class="phone-address-row"><ConnectionQRCode :value="address"/><div class="phone-scan-details"><strong>用 iPhone 相机扫码</strong><p>打开连接页，再输入上面的 8 位配对码。</p><code>{{address}}</code><button :disabled="busy" @click="emit('copy',address)"><Copy :size="17"/>复制地址</button></div></div><p v-if="!status.addresses?.length">未找到 Wi-Fi 局域网地址，请连接网络后停止并重新开启。</p></div><p class="phone-connection-note">在 Safari 分享菜单中选择「添加到主屏幕」。请在可信 Wi-Fi 下使用，保持 Mac 唤醒。停止连接或退出拾流后，手机需要重新配对。</p></template></div></template>
<style scoped>.phone-settings-heading{display:flex;align-items:center;gap:24px;justify-content:space-between}.phone-settings-heading>div{max-width:680px}.phone-settings-heading p{font-size:14px;color:#6f819b;line-height:1.7;margin-top:8px}.phone-settings-heading button{flex-shrink:0}.phone-pair-info{display:flex;align-items:center;gap:24px;justify-content:space-between;background:#f5fbfc;border:1px solid #dfebee;border-radius:12px;margin-top:20px;padding:20px}.phone-pair-info label{display:block;font-size:13px;color:#6f819b}.phone-pair-code{display:block;font-size:30px;letter-spacing:5px;color:#118e99;margin:10px 0}.phone-pair-info p,.phone-connection-note{font-size:13px;color:#6f819b;line-height:1.6}.phone-addresses{display:grid;gap:10px;margin:18px 0}.phone-addresses>div{display:flex;align-items:center;justify-content:space-between;gap:18px}.phone-addresses code{overflow-wrap:anywhere;font-size:14px}.phone-addresses button{flex-shrink:0}.phone-connection-note{margin-top:15px}.phone-address-row{justify-content:flex-start!important;padding:18px;border:1px solid #dfebee;border-radius:12px;background:#f9fcff}.phone-scan-details{display:grid;gap:10px;min-width:0}.phone-scan-details p{font-size:13px;color:#6f819b;line-height:1.6}.phone-scan-details button{justify-self:start}.phone-scan-details strong{font-size:16px}</style>
